<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { ITEMS, CATEGORIES, SKILLS, EQUIPMENT, CERTIFICATES, EVENTS, QUESTS, THEMES, CHARACTERS } from '../content';
import { capacity, displayCapacity, attraction } from '../game/engine';
import { state, modal, selectedItem, selectedOrder, dispatch, downloadSave, uploadSave, restore, fullScreen, muted, volume, reducedMotion, started, inspectSave } from './store';
import type { CategoryId } from '../game/types';
import Art from './Art.vue';
import ItemKnowledge from './ItemKnowledge.vue';
import { BALANCE, CHALLENGES } from '../game/balance';
const groupNames: Record<string, string> = { neighborhood: '街区互助社', union: '工造联合会', grayline: '灰线商团' };
const category = ref('all'); const equipmentType = ref('tool'); const tab = ref('general');
const respecMode = ref(false); const plan = ref<string[]>([]);
const stock = computed(() => state.value.items.filter(i => i.owner === 'player' && (category.value === 'all' || ITEMS.find(d => d.id === i.definitionId)?.category === category.value)));
const selected = computed(() => state.value.items.find(i => i.id === selectedItem.value && i.owner === 'player') ?? stock.value[0]);
const definition = computed(() => ITEMS.find(d => d.id === selected.value?.definitionId));
const displays = computed(() => state.value.items.filter(i => i.location === 'display'));
const branches = computed(() => [...new Set(SKILLS.filter(s => s.tree === tab.value).map(s => s.branch))]);
const currentEvent = computed(() => EVENTS.find(e => e.id === state.value.eventId));
const planCost = computed(() => SKILLS.filter(s => plan.value.includes(s.id)).reduce((n, s) => n + s.cost, 0));
const currentCost = computed(() => SKILLS.filter(s => state.value.skills.includes(s.id)).reduce((n, s) => n + s.cost, 0));
const lost = computed(() => SKILLS.filter(s => state.value.skills.includes(s.id) && !plan.value.includes(s.id)));
const gained = computed(() => SKILLS.filter(s => !state.value.skills.includes(s.id) && plan.value.includes(s.id)));
const name = (id: string) => ITEMS.find(d => d.id === id)?.name ?? id;
watch(() => modal.value, () => { respecMode.value = false; });
function startOwn() { if (selected.value && dispatch({ type: 'startRepair', itemId: selected.value.id })) { selectedOrder.value = state.value.orders.find(o => o.itemId === selected.value?.id && !o.delivered)?.id ?? ''; modal.value = 'workbench'; } }
function learn(id: string) { if (respecMode.value) plan.value = plan.value.includes(id) ? plan.value.filter(s => s !== id) : [...plan.value, id]; else dispatch({ type: 'learn', skillId: id }); }
function drop(e: DragEvent) { const id = e.dataTransfer?.getData('text/plain'); if (id) dispatch({ type: 'display', itemId: id }); }
function exam(id: typeof CERTIFICATES[number]['id']) { if (dispatch({ type: 'exam', certificate: id })) { selectedOrder.value = state.value.orders.find(o => o.kind === 'exam' && o.certificate === id && !o.delivered)?.id ?? ''; modal.value = 'workbench'; } }
function finalOrder() { if (dispatch({ type: 'startFinal' })) { selectedOrder.value = state.value.orders.find(o => o.kind === 'final' && !o.delivered)?.id ?? ''; modal.value = 'workbench'; } }
</script>

<template>
  <div class="notebook-content">
    <template v-if="modal === 'inventory'">
      <div class="panel-heading"><p class="eyebrow">STOCKROOM / 每件旧物，都有去处</p><h2>货架与库存</h2><p>库存容量 {{ capacity(state) }} · 拖动物品到展示区，或选中后点击入柜。</p></div>
      <div class="actions compact"><select v-model="category" aria-label="库存分类"><option value="all">全部分类</option><option v-for="c in CATEGORIES" :key="c.id" :value="c.id">{{ c.name }}</option></select><button @click="dispatch({ type: 'sort' })">快捷整理</button></div>
      <div class="inventory-layout"><div class="inventory-grid"><button v-for="item in stock" :key="item.id" :data-item="item.id" :class="['item-tile', { selected: item.id === selected?.id }]" draggable="true" @dragstart="$event.dataTransfer?.setData('text/plain', item.id)" @click="selectedItem = item.id"><Art :id="item.definitionId" :label="name(item.definitionId)" /><strong>{{ name(item.definitionId) }}</strong><small>{{ item.location === 'display' ? '已陈列' : item.location === 'workshop' ? '维修中' : '在货架' }} · 成本 ₡{{ item.cost }}</small></button><p v-if="!stock.length" class="empty-note">货架暂时空了。可以到柜台收货，或接基础维修积攒现金。</p></div>
        <aside v-if="selected && definition" class="item-inspector"><p class="eyebrow">{{ CATEGORIES.find(c => c.id === definition?.category)?.name }}</p><h3>{{ definition.name }}</h3><p>{{ definition.description }}</p><dl><dt>外观</dt><dd>{{ selected.known.includes('basic') ? selected.condition + '%' : '待检查' }}</dd><dt>实际累计成本</dt><dd>₡{{ selected.cost }}</dd><dt>占用</dt><dd>{{ definition.size }} 格</dd><dt>保存至</dt><dd>{{ !selected.known.includes('basic') ? '待检查' : selected.expiresDay === null ? '长期' : `第${selected.expiresDay}日` }}</dd><template v-if="selected.known.includes('scan') && definition.category === 'energy'"><dt>有效容量</dt><dd>{{ selected.capacity }}%</dd></template><template v-if="selected.known.includes('scan') && definition.category === 'energy'"><dt>纯度</dt><dd>{{ selected.purity }}%</dd></template><template v-if="selected.known.includes('scan') && definition.category === 'data'"><dt>数据完整度</dt><dd>{{ selected.integrity }}%</dd></template><template v-if="selected.known.includes('serial')"><dt>鉴定</dt><dd>{{ selected.authentic ? '真实原物' : '仿品 / 来源存疑' }}</dd><dt>出处</dt><dd>{{ selected.provenance }}</dd></template></dl>
          <ItemKnowledge :item="selected" /><div class="vertical-actions"><button @click="dispatch({ type: 'inspect', itemId: selected.id })">检查物品</button><button @click="dispatch({ type: 'inspect', itemId: selected.id, method: 'scan' })">多谱扫描</button><button @click="dispatch({ type: 'inspect', itemId: selected.id, method: 'serial' })">查验来源</button><button v-if="definition.certificate" @click="startOwn">送到工作台翻新</button><button v-if="selected.location !== 'display'" @click="dispatch({ type: 'display', itemId: selected.id })">放进收藏展示柜</button><button v-else @click="dispatch({ type: 'withdraw', itemId: selected.id })">撤展并返回货架</button><button v-if="definition.category === 'food'" @click="dispatch({ type: 'preserve', itemId: selected.id })">使用保鲜包</button><button class="danger-text" v-if="selected.location === 'stock'" @click="dispatch({ type: 'liquidate', itemId: selected.id })">折价清货</button></div>
        </aside></div>
      <div class="display-drop" @dragover.prevent @drop.prevent="drop">将已鉴定的自有物品拖到这里陈列 · 或使用物品详情中的“放进收藏展示柜”</div>
    </template>

    <template v-else-if="modal === 'growth'">
      <div class="panel-heading"><p class="eyebrow">CRAFT / 让手艺成为你的招牌</p><h2>技能与资质 <small>{{ state.points }} 点可分配</small></h2><p>等级 {{ state.level }} · 经验 {{ state.xp }} · 两棵树共用点数。大师需维修树先投入 6 点，再支付 2 点。</p></div>
      <div class="tab-row"><button :class="{ active: tab === 'general' }" @click="tab = 'general'">通用经营</button><button :class="{ active: tab === 'repair' }" @click="tab = 'repair'">修复师专精</button><button :class="{ active: tab === 'certificates' }" @click="tab = 'certificates'">证书与许可</button></div>
      <template v-if="tab !== 'certificates'"><div class="skill-columns"><section v-for="branch in branches" :key="branch"><h3>{{ branch }}</h3><button v-for="skill in SKILLS.filter(s => s.branch === branch && s.tree === tab)" :key="skill.id" :data-skill="skill.id" :class="['skill-node', { learned: (respecMode ? plan : state.skills).includes(skill.id), master: skill.tier === 4 }]" @click="learn(skill.id)"><span class="skill-tier">{{ String(skill.tier).padStart(2, '0') }} / {{ skill.cost }} 点</span><strong>{{ skill.name }} <i v-if="(respecMode ? plan : state.skills).includes(skill.id)">✓</i></strong><p>{{ skill.description }}</p><small v-if="skill.requires.length">前置：{{ skill.requires.map(id => SKILLS.find(s => s.id === id)?.name).join('、') }}</small></button></section></div>
        <div class="respec"><button v-if="!respecMode" @click="respecMode = true; plan = [...state.skills]">预览技能重配</button><template v-else><h3>重配预览</h3><p>闭店且没有进行中的专精工单才可结算。{{ state.freeRespec ? '本次免费。' : `本次收费 ₡${BALANCE.respecPrice}，确认后一次性扣款。` }}</p><p>计划消耗 {{ planCost }} / 可用 {{ state.points + currentCost }} 点</p><p>失去：{{ lost.map(s => s.name).join('、') || '无' }}</p><p>获得：{{ gained.map(s => s.name).join('、') || '无' }}</p><div class="actions"><button class="primary" @click="dispatch({ type: 'respec', skills: plan }) && (respecMode = false)">确认一次性重配</button><button @click="respecMode = false">取消</button><button @click="plan = []">清空预览</button></div></template></div>
      </template>
      <div v-else class="certificate-list"><section v-for="cert in CERTIFICATES" :key="cert.id" :data-certificate="cert.id" class="certificate"><span class="eyebrow">{{ state.certificates.includes(cert.id) ? '已持证 ✓' : '尚未取得' }}</span><h3>{{ cert.name }}</h3><p>{{ cert.description }}</p><p>所需案例 {{ cert.cases }} · 培训 ₡{{ cert.fee }} · 第 {{ cert.chapter }} 章起</p><div v-if="!state.certificates.includes(cert.id)" class="actions"><button v-if="!state.trained.includes(cert.id)" @click="dispatch({ type: 'train', certificate: cert.id })">报名培训</button><button v-else class="primary" @click="exam(cert.id)">进入实际考核 / 重试</button></div></section><section class="certificate"><p class="eyebrow">通用经营资质</p><h3>受管制器件交易许可</h3><p>许可用于合法买卖神经和医疗器件，维修能力仍由证书决定。</p><button :disabled="state.licenses.length > 0" @click="dispatch({ type: 'license' })">{{ state.licenses.length ? '已取得交易许可 ✓' : `申请通用交易许可 · ₡${BALANCE.licensePrice}` }}</button></section></div>
    </template>

    <template v-else-if="modal === 'equipment'">
      <div class="panel-heading"><p class="eyebrow">SUPPLIES / 好工具，陪你久一点</p><h2>工具与设施采购</h2><p>工具扩展检测与维修能力。耗材按工序消耗，设施改善库存、保存和陈列。</p></div><div class="tab-row"><button :class="{ active: equipmentType === 'tool' }" @click="equipmentType = 'tool'">六件工具</button><button :class="{ active: equipmentType === 'material' }" @click="equipmentType = 'material'">六类耗材</button><button :class="{ active: equipmentType === 'facility' }" @click="equipmentType = 'facility'">四类设施</button></div><div class="equipment-grid"><article v-for="eq in EQUIPMENT.filter(e => e.type === equipmentType)" :key="eq.id" :data-equipment="eq.id"><Art :id="eq.id" :label="eq.name" /><div><span class="eyebrow">持有 {{ state.equipment[eq.id] ?? 0 }}</span><h3>{{ eq.name }}</h3><p>{{ eq.description }}</p><button @click="dispatch({ type: 'buyEquipment', equipmentId: eq.id })">采购 · ₡{{ eq.price }}</button></div></article></div>
    </template>

    <template v-else-if="modal === 'collection'">
      <div class="panel-heading"><p class="eyebrow">COLLECTION / 为它留一盏灯</p><h2>收藏展示柜</h2><p>{{ displays.length }} / {{ displayCapacity(state) }} 格 · 吸引力 {{ Math.round(attraction(state)) }} · 同款重复收益递减</p></div><div class="display-shelf" @dragover.prevent @drop.prevent="drop"><article v-for="item in displays" :key="item.id"><Art :id="item.definitionId" :label="name(item.definitionId)" /><h3>{{ name(item.definitionId) }}</h3><p>{{ item.provenance }}</p><small>原貌 {{ item.originality }}% · 品相 {{ item.condition }}%</small><button @click="dispatch({ type: 'withdraw', itemId: item.id })">撤展</button></article><button v-if="displays.length < displayCapacity(state)" class="empty-slot" @click="modal = 'inventory'">＋<span>从库存选择藏品</span></button></div><div class="theme-list"><article v-for="theme in THEMES" :key="theme.id"><h3>{{ theme.name }}</h3><p>{{ theme.description }}</p><p>{{ theme.items.map(name).join(' · ') }}</p><small>已展出 {{ theme.items.filter(id => displays.some(i => i.definitionId === id)).length }} / {{ theme.items.length }}</small></article></div><h3>旧物图鉴 · {{ state.discovered.length }} / {{ ITEMS.length }}</h3><div class="catalog-grid"><div v-for="item in ITEMS" :key="item.id" :class="{ undiscovered: !state.discovered.includes(item.id) }"><Art v-if="state.discovered.includes(item.id)" :id="item.id" :label="item.name" /><span v-else>?</span><small>{{ state.discovered.includes(item.id) ? item.name : '尚未见过' }}</small></div></div>
    </template>

    <template v-else-if="modal === 'journal'">
      <div class="panel-heading"><p class="eyebrow">DISTRICT NOTES / 一间店与一条街</p><h2>街区手记</h2><p>声望 {{ state.reputation }} · 关系会改变供货、客户与订单。</p></div><div class="journal-layout"><section><article v-if="currentEvent" class="event-story"><span class="eyebrow">今日消息</span><h3>{{ currentEvent.name }}</h3><p>{{ currentEvent.text }}</p><p>{{ CATEGORIES.find(c => c.id === currentEvent?.category)?.name }} 行情 ×{{ currentEvent.multiplier }}</p><div v-if="!state.eventResolved" class="vertical-actions"><button v-for="(choice, index) in currentEvent.choices" :key="index" @click="dispatch({ type: 'eventChoice', index })">{{ choice.label }}<small>{{ choice.description }} · 现金 {{ choice.cash >= 0 ? '+' : '' }}{{ choice.cash }} · 声望 {{ choice.reputation >= 0 ? '+' : '' }}{{ choice.reputation }}</small></button></div><p v-else class="muted">今天的选择已经记在账本里。</p></article><article v-for="quest in QUESTS" :key="quest.id" :data-quest="quest.id" class="quest-story"><span class="eyebrow">{{ CHARACTERS.find(c => c.id === quest.character)?.name }} · {{ Math.min((state.questStages[quest.id] ?? 0) + 1, quest.stages.length) }} / {{ quest.stages.length }}</span><h3>{{ quest.name }}</h3><template v-if="(state.questStages[quest.id] ?? 0) < quest.stages.length"><p>{{ quest.stages[state.questStages[quest.id] ?? 0].text }}</p><p class="small">奖励 ₡{{ quest.stages[state.questStages[quest.id] ?? 0].reward }} · {{ quest.stages[state.questStages[quest.id] ?? 0].xp }} 经验</p><button @click="dispatch({ type: 'claimQuest', questId: quest.id })">核对进展并交付</button></template><p v-else>这段故事已经收束。街区还记得你的帮助。</p></article></section><aside><article class="final-quest"><p class="eyebrow">永久经营权</p><h3>自己的招牌</h3><p>取得一个维修大师能力，修复街区联络中枢，再支付 ₡12,000 收购款。</p><p>中枢进度 {{ state.finalStage }} / 3</p><button class="wide" v-if="!state.finalComplete" @click="finalOrder">接取下一阶段最终委托</button><button class="primary wide" :disabled="!state.finalComplete || state.victory" @click="dispatch({ type: 'buyShop' })">{{ state.victory ? '已拥有永久经营权 ✓' : '支付并买下店铺' }}</button></article><article><h3>预约货源</h3><select :value="state.appointments ?? ''" aria-label="预约商品分类" @change="dispatch({ type: 'appoint', category: (($event.target as HTMLSelectElement).value || null) as CategoryId | null })"><option value="">随街区而来</option><option v-for="c in CATEGORIES" :key="c.id" :value="c.id">{{ c.name }}</option></select><p class="small muted">定向采购技能开放后生效。</p></article><article v-if="state.endless"><h3>珍品与工坊挑战</h3><p v-if="state.challenge">{{ CHALLENGES.find(c => c.id === state.challenge?.id)?.name }} · {{ state.challenge.progress }}/{{ state.challenge.goal }} · 第{{ state.challenge.deadline }}日截止 · 奖励 ₡{{ state.challenge.reward }}</p><template v-else><p>自愿接取，未达标只失去该次奖励，经营权和藏品保留。</p><div v-for="challenge in CHALLENGES" :key="challenge.id"><p>{{ challenge.name }} · {{ challenge.description }} {{ challenge.days }} 日内完成，登记费 ₡{{ challenge.fee }}，奖励 ₡{{ challenge.reward }}；未完成仅损失登记费和奖励机会。</p><button @click="dispatch({ type: 'challenge', id: challenge.id })">接取{{ challenge.name }}</button></div></template></article><article><h3>往来记录</h3><p v-for="(relation, group) in state.relations" :key="group">{{ groupNames[group] ?? group }} <b>{{ relation }}</b></p></article></aside></div>
      <details class="ledger"><summary>展开经营账本 · {{ state.ledger.length }} 笔记录</summary><div v-for="entry in state.ledger.slice(-40).reverse()" :key="entry.id"><span>第{{ entry.day }}日 · {{ entry.note }}</span><b>{{ entry.amount >= 0 ? '+' : '' }}{{ entry.amount }}</b></div></details>
    </template>

    <template v-else-if="modal === 'settings'">
      <div class="panel-heading"><p class="eyebrow">SETTINGS / 歇一会儿也好</p><h2>存档与设置</h2><p>每次经营操作自动保存。本机与正式域名存储独立，使用导出、导入迁移。</p></div><div class="settings-layout"><section><h3>保存进度</h3><div class="vertical-actions"><button @click="downloadSave">导出当前存档</button><label class="file-button">导入存档<input type="file" accept=".json,application/json" @change="uploadSave(($event.target as HTMLInputElement).files?.[0])" /></label><button @click="restore">恢复营业日开始备份</button><button @click="started = false; modal = ''; inspectSave()">保存并返回标题</button></div><p class="small muted">导入前会校验版本与数据。存档格式 v{{ state.version }} · 内容 {{ state.contentVersion }} · 数值 {{ state.balanceVersion }}</p></section><section><h3>声音与显示</h3><label class="check-row"><input v-model="muted" type="checkbox" /> 静音</label><label class="field-label">音量 {{ Math.round(volume * 100) }}%<input v-model.number="volume" type="range" min="0" max="1" step="0.05" /></label><label class="check-row"><input v-model="reducedMotion" type="checkbox" /> 减少动态效果</label><button @click="fullScreen">切换全屏 · F</button><p class="small muted">Esc 关闭面板或退出全屏。手机请使用横屏。</p><a href="/notes/cyber-shop/">返回博客游戏介绍 ↗</a></section></div>
    </template>

    <template v-else><div class="panel-heading"><p class="eyebrow">FIELD GUIDE / 开店第一课</p><h2>欢迎来到第九街。</h2><p>思考不消耗现实时间。只有执行操作才消耗工时，点击闭店才结束营业日。</p></div><div class="guide-columns"><section><h3>收货与交易</h3><p>客人带来的商品可以检查、议价、收购。货架上的物品卖给偏好相符的买家；现金紧张时可折价清货。</p><p>食品会临期，电源看容量，材料看纯度，数据看完整度，神经器件看许可，古董看原貌和出处。</p></section><section><h3>修好一件物品</h3><p>接单后打开工作台，检测得到线索。选择工序和操作位置，校准时将读数调到目标。全部故障排除后复检，最后交付。</p><p>客户预付款专用于材料。没有现金时，从工作台接基础援助维修即可恢复经营。</p></section><section><h3>留下你的招牌</h3><p>完成委托获得经验和点数。维修与通用树共用点数，需要集中一条专精取得大师。考取证书扩大维修范围。</p><p>修复联络中枢并买下店铺即可通关。之后免租自由经营，积累点数、考古董证书、追寻收藏。</p></section></div></template>
  </div>
</template>
